#include <cassert>
#include <climits>

int main() {
    // Fixed width: int is 32-bit, long long 64-bit on mainstream 64-bit platforms.
    assert(INT_MAX == 2147483647);
    assert(LLONG_MAX == 9223372036854775807LL);
    long long big = 1LL << 62;  // fits; 2^100 fits in no built-in type
    assert(big == 4611686018427387904LL);
    // Signed overflow is undefined behaviour: check BEFORE adding.
    int a = INT_MAX, b = 1;
    bool would_overflow = a > INT_MAX - b;
    assert(would_overflow);
    // Bit length of a positive value via count-leading-zeros (GCC builtin).
    unsigned long long x = 1000;
    assert(64 - __builtin_clzll(x) == 10);
    assert(__builtin_popcountll(255ULL) == 8);
    return 0;
}

#include <cassert>
#include <cstdlib>

int main() {
    // Integer division truncates toward zero (guaranteed since C++11).
    assert(-7 / 2 == -3);
    assert(7 / -2 == -3);
    // % takes the sign of the dividend, so (a / b) * b + a % b == a.
    assert(-7 % 2 == -1);
    assert(7 % -2 == 1);
    // A modulo in [0, m) needs a fix-up.
    int m = 5, a = -7;
    assert(((a % m) + m) % m == 3);
    // std::div returns quotient and remainder together.
    std::div_t d = std::div(-7, 2);
    assert(d.quot == -3 && d.rem == -1);
    // int / int stays int.
    assert(7 / 2 == 3);
    return 0;
}

#include <algorithm>
#include <cassert>
#include <climits>
#include <limits>
#include <vector>

int main() {
    const int INF = INT_MAX;
    std::vector<int> dist = {0, INF, 4};
    int w = 3;
    // INF + w would overflow (undefined behaviour): guard before adding.
    int candidate = (dist[1] == INF) ? INF : dist[1] + w;
    assert(candidate == INF);
    // Common workaround: a sentinel with headroom.
    const int SAFE_INF = 1000000000;
    assert(SAFE_INF <= INT_MAX - SAFE_INF);  // 2e9 still fits in 32 bits
    // Floating-point infinity exists but mixes poorly with int code.
    double dinf = std::numeric_limits<double>::infinity();
    assert(dinf + 1 == dinf);
    assert(std::min(INF, 3) == 3);
    return 0;
}

#include <cassert>
#include <cstdint>

int main() {
    int x = 5;
    assert(~x == -6);  // two's complement: ~x == -(x + 1)
    assert((6 & 3) == 2 && (6 | 3) == 7 && (6 ^ 3) == 5);
    // Unsigned arithmetic wraps modulo 2^32 (well defined).
    uint32_t u = 0xFFFFFFFFu;
    u += 1;
    assert(u == 0);
    // uint32 -> int32: implementation-defined before C++20 (g++ wraps).
    uint32_t bits = 0xFFFFFFFEu;
    assert(static_cast<int32_t>(bits) == -2);
    // 1 << 40 needs a 64-bit operand.
    uint64_t big = 1ULL << 40;
    assert(big == 1099511627776ULL);
    return 0;
}

#include <cassert>
#include <string>

int main() {
    std::string s = "abc";
    s[0] = 'x';  // std::string is mutable
    assert(s == "xbc");
    std::string out;
    for (char c = 'a'; c <= 'e'; ++c) out += c;  // amortized O(1) append
    assert(out == "abcde");
    char c = 'd';
    assert(c - 'a' == 3);  // char is a small integer type
    assert(static_cast<char>('a' + 2) == 'c');
    return 0;
}

#include <cassert>
#include <string>
#include <string_view>

int main() {
    std::string s = "interview";
    assert(s.substr(2, 3) == "ter");   // (pos, count), and it copies
    std::string_view v(s);
    assert(v.substr(2, 3) == "ter");   // view: O(1), no copy
    std::string r(s.rbegin(), s.rend());
    assert(r == "weivretni");
    assert(s.back() == 'w');           // no negative indexes
    return 0;
}

#include <cassert>
#include <vector>

int main() {
    std::vector<int> a = {1, 2, 3};
    std::vector<int> b = a;  // full copy (value semantics)
    b[0] = 99;
    assert(a[0] == 1);
    std::vector<int>& alias = a;  // aliasing must be explicit
    alias[0] = 7;
    assert(a[0] == 7);
    int rows = 2, cols = 3;
    // Each row is an independent copy of the prototype row.
    std::vector<std::vector<int>> grid(rows, std::vector<int>(cols, 0));
    grid[0][0] = 1;
    assert(grid[1][0] == 0);
    return 0;
}

#include <cassert>
#include <vector>

int main() {
    std::vector<std::vector<int>> g = {{1, 2}, {3, 4}};
    auto copy = g;  // copies every inner vector too
    copy[0][0] = 9;
    assert(g[0][0] == 1);
    std::vector<int> a = {1, 2}, b = {1, 2};
    assert(a == b);    // value equality
    assert(&a != &b);  // different objects
    int* p = nullptr;
    assert(p == nullptr);
    return 0;
}

#include <cassert>
#include <vector>

int main() {
    std::vector<int> a = {10, 20, 30};
    int sum = 0;
    for (int i = 0; i < (int)a.size(); ++i) sum += i * a[i];
    assert(sum == 1 * 20 + 2 * 30);
    std::vector<int> seen;
    for (int i = 0; i < 10; i += 3) seen.push_back(i);  // i is a real counter
    assert((seen == std::vector<int>{0, 3, 6, 9}));
    std::vector<int> stack;
    assert(stack.empty());  // explicit emptiness check
    std::vector<int> rev(a.rbegin(), a.rend());
    assert((rev == std::vector<int>{30, 20, 10}));
    return 0;
}
